const cfg = {};
for (const i of $('Ler configuração').all()) { const r = i.json || {}; if (r.chave) cfg[r.chave] = { valor: String(r.valor ?? '').trim(), status: String(r.status || '').toUpperCase() }; }
const val = (k, d) => (cfg[k] && cfg[k].valor && cfg[k].status !== 'PENDENTE' && cfg[k].status !== 'OBSOLETO' ? cfg[k].valor : d);
const p = $('Saída da IA').first().json;
let s = p.saida;
if (typeof s === 'string') { try { s = JSON.parse(s); } catch (e) { s = {}; } }
s = s || {};
const dealId = Number(p.deal_id) || 0;
const personId = Number(p.person_id) || 0;
const numero = String(p.numero || '');
if (!dealId) return [];
const BASE = 'https://api.pipedrive.com';
const owner = Number(val('PD_ALERTA_USER_ID', '0')) || undefined;
const hoje = new Date(Date.now() - 3 * 3600000).toISOString().slice(0, 10);
const etapa = {
  'Em conversa': val('ETAPA_EM_CONVERSA', ''), 'Diagnóstico entregue': val('ETAPA_DIAGNOSTICO_ENTREGUE', ''),
  'Reunião marcada': val('ETAPA_REUNIAO_MARCADA', ''), 'Proposta enviada': val('ETAPA_PROPOSTA_ENVIADA', ''),
  'Em decisão': val('ETAPA_EM_DECISAO', ''), 'Contrato': val('ETAPA_CONTRATO', '')
};
const ops = [];
const notas = [];
const add = (method, url, body, descricao) => ops.push({ method, url: BASE + url, body, descricao });
const tarefa = (subject, note, due) => add('POST', '/api/v2/activities', {
  subject, type: 'task', deal_id: dealId, owner_id: owner, due_date: due || hoje,
  participants: personId ? [{ person_id: personId, primary: true }] : undefined, note
}, 'Tarefa: ' + subject);
const moverPara = (nome) => { const id = etapa[nome]; if (id) add('PATCH', '/api/v2/deals/' + dealId, { stage_id: Number(id) }, 'Mover para ' + nome); else notas.push('⚠ Etapa "' + nome + '" sem ID em atom_config: o card não foi movido.'); };
const acao = String(s.acao || 'nenhuma');
if (acao === 'mover_etapa') moverPara(String(s.etapa_destino || ''));
if (acao === 'marcar_reuniao') {
  const ms = Date.parse(s.data_reuniao || '');
  if (ms) {
    const iso = new Date(ms).toISOString();
    const revisao = s.tipo_reuniao === 'revisao';
    add('POST', '/api/v2/activities', {
      subject: (revisao ? 'Revisão da proposta' : 'Reunião de diagnóstico') + ' (marcada pela IA)', type: 'meeting', deal_id: dealId, owner_id: owner,
      due_date: iso.slice(0, 10), due_time: iso.slice(11, 16), duration: revisao ? '00:15' : '00:20',
      participants: personId ? [{ person_id: personId, primary: true }] : undefined,
      note: 'Marcada pela IA do número ' + numero + '. Confira o horário na agenda do Thiago.'
    }, 'Criar ' + (revisao ? 'revisão' : 'reunião'));
    if (!revisao) moverPara('Reunião marcada');
  } else notas.push('⚠ A IA pediu para marcar reunião, mas a data veio inválida: ' + (s.data_reuniao || '(vazia)'));
}
if (acao === 'registrar_aceite') {
  moverPara('Contrato');
  tarefa('Aceite registrado pela IA: conferir e liberar o contrato', 'Opção escolhida: ' + (s.opcao_escolhida || '(não informada)') + '. Confira valores e condições antes da formalização.');
}
if (acao === 'reenviar_contrato') tarefa('Cliente pediu o reenvio do contrato', 'Pedido recebido pela IA do número ' + numero + '. Confira o e-mail do signatário e reenvie.');
if (acao === 'transferir_thiago') {
  tarefa('[URGENTE] Responder o cliente pessoalmente', 'A IA do número ' + numero + ' transferiu a conversa. Motivo e contexto na nota mais recente.');
  const campo = val('PD_DEAL_IA_PAUSADA', '');
  if (campo) { const cf = {}; cf[campo] = val('PD_DEAL_IA_PAUSADA_SIM', 'Sim'); add('PATCH', '/api/v2/deals/' + dealId, { custom_fields: cf }, 'Pausar a IA neste negócio'); }
  else notas.push('⚠ Campo PD_DEAL_IA_PAUSADA não configurado: a IA não ficou pausada.');
}
if (acao === 'perdido') {
  const motivo = String(s.motivo_perda || 'Sem motivo informado').slice(0, 250);
  add('PATCH', '/api/v2/deals/' + dealId, { status: 'lost', lost_reason: motivo }, 'Marcar como perdido: ' + motivo);
  if (/momento/i.test(motivo) && s.data_retomada) {
    const d = String(s.data_retomada);
    const due = /^\d{4}-\d{2}$/.test(d) ? d + '-05' : (/^\d{4}-\d{2}-\d{2}/.test(d) ? d.slice(0, 10) : '');
    if (due) tarefa('Retomar contato combinado com o cliente', 'O cliente pediu para retomar nesta data. Leve um Raio-X atualizado.', due);
    else notas.push('Retomada combinada: ' + d + ' (data não reconhecida; crie a tarefa à mão).');
  }
}
if (acao === 'nao_contatar') {
  const campo = val('PD_PERSON_NAO_CONTATAR', '');
  if (personId && campo) { const cf = {}; cf[campo] = val('PD_PERSON_NAO_CONTATAR_SIM', 'Sim'); add('PATCH', '/api/v2/persons/' + personId, { custom_fields: cf }, 'Marcar pessoa como Não contatar'); }
  add('PATCH', '/api/v2/deals/' + dealId, { status: 'lost', lost_reason: 'Não contatar' }, 'Marcar como perdido: Não contatar');
}
const c = s.campos || {};
const dados = Object.keys(c).filter((k) => c[k] !== '' && c[k] !== null && c[k] !== undefined).map((k) => k + ': ' + c[k]).join(' · ');
const linhas = [];
if (s.nota) linhas.push(String(s.nota));
if (dados) linhas.push('Dados informados: ' + dados);
if (s.gancho_usado) linhas.push('Gancho usado: ' + s.gancho_usado);
for (const n of notas) linhas.push(n);
const modo = val('MODO_EXECUCAO', 'SIMULACAO').toUpperCase();
const sandbox = val('SANDBOX_DEAL_IDS', '').split(',').map((x) => x.trim());
const real = modo === 'PRODUCAO' || (modo === 'SANDBOX' && sandbox.includes(String(dealId)));
if (!real) {
  linhas.push('<b>[SIMULAÇÃO]</b> Ações que seriam executadas: ' + (ops.length ? ops.map((o) => o.descricao).join('; ') : 'nenhuma'));
  return [{ json: { method: 'POST', url: BASE + '/v1/notes', body: { deal_id: dealId, content: '<b>IA · número ' + numero + '</b><br>' + linhas.join('<br>') }, descricao: 'Nota (simulação)' } }];
}
if (linhas.length) add('POST', '/v1/notes', { deal_id: dealId, content: '<b>IA · número ' + numero + '</b><br>' + linhas.join('<br>') }, 'Nota da conversa');
return ops.map((o) => ({ json: o }));

const planos = $('Planejar ações').all();
const res = $input.all();
const itens = res.map((r, i) => ({ acao: (planos[i] && planos[i].json.descricao) || '', ok: r.json.statusCode >= 200 && r.json.statusCode < 300, status: r.json.statusCode, erro: r.json.statusCode >= 300 ? JSON.stringify(r.json.body || {}).slice(0, 300) : '' }));
return [{ json: { total: itens.length, falhas: itens.filter((x) => !x.ok).length, itens } }];
